  /// Builds a presentation of the held credential [credentialId] in answer
  /// to [request], ready to send to the requester: the credential as issued,
  /// the disclosures of exactly the claims the request's query names, and
  /// the request's nonce and domain, signed by the holder key
  /// (`Ed25519Signature2020` over the RFC 8785 form without `proof`).
  ///
  /// Throws a [WalletException] if the credential is not held or has
  /// expired, if it lacks a requested claim, or if the query asks for more
  /// than one credential or offers claim sets. The credential stays held.
  Future<Map<String, dynamic>> createPresentation(
    String credentialId,
    PresentationRequest request,
  ) async {
    final credential = _store.byId(credentialId);
    if (credential == null) {
      throw WalletException('No credential $credentialId');
    }
    final now = _now().millisecondsSinceEpoch ~/ 1000;
    final expiresAt = credential.vc['expires_at'];
    if (expiresAt is! int) {
      throw WalletException('Credential $credentialId has no expiry');
    }
    if (now > expiresAt) {
      throw WalletException('Credential $credentialId expired at $expiresAt');
    }
    final disclosures = [
      for (final name in _requestedClaims(request))
        credential.disclosures.firstWhere(
          (d) => d.name == name,
          orElse: () => throw WalletException(
            'Credential $credentialId has no claim $name',
          ),
        ),
    ];

    final key = holderKey();
    final presentation = <String, dynamic>{
      '@context': ['https://www.w3.org/2018/credentials/v1'],
      'type': ['VerifiablePresentation'],
      'holder': key.did,
      'verifiableCredential': credential.vc,
      'disclosures': [for (final d in disclosures) d.toJson()],
      'nonce': request.nonce,
      'domain': request.domain,
    };
    final signature = await key.sign(
      utf8.encode(JcsUtil.canonicalize(presentation)),
    );
    presentation['proof'] = {
      'type': 'Ed25519Signature2020',
      'created': now,
      'verificationMethod': key.keyId,
      'proofPurpose': 'authentication',
      'proofValue': toMultiBase(signature),
    };
    return presentation;
  }

  /// The claims [request] names: the last element of each claim path in its
  /// one credential query.
  static Set<String> _requestedClaims(PresentationRequest request) {
    final queries = request.dcqlQuery.credentials.toList();
    if (queries.length != 1) {
      throw WalletException(
        'Request asks for ${queries.length} credentials; only one is supported',
      );
    }
    if (queries.single.claimSets != null) {
      throw const WalletException('Requests with claim_sets are not supported');
    }
    final names = <String>{};
    for (final claim in queries.single.claims ?? const []) {
      final name = claim.path.isEmpty ? null : claim.path.last;
      if (name is! String) {
        throw WalletException('Unsupported claim path ${claim.path}');
      }
      names.add(name);
    }
    return names;
  }
}

