import 'dart:convert';
import 'dart:io';

import 'package:credentials_app/credentials_app.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:ssi/ssi.dart';

import 'fake_issuer_client.dart';
import 'fixtures.dart';

/// 2026-06-01T00:00:00Z, the backend suite's `NOW`.
const now = 1780272000;

/// The presentation the backend verifier checks
/// (`backend/tests/wallet_presentation.rs`). Regenerate with
/// `WALLET_VECTOR_UPDATE=1 flutter test test/create_presentation_test.dart`.
final vectorFile = File('test/fixtures/wallet_presentation.json');

final credentialId = backendIssuance()['credential']['id'] as String;

WalletService walletAt(int unixSeconds) => WalletService(
  issuer: FakeIssuerClient(),
  store: CredentialStore()..save(HeldCredential.fromIssuance(backendIssuance())),
  newKey: () => HolderKey.fromSeed(holderSeed),
  now: () => DateTime.fromMillisecondsSinceEpoch(unixSeconds * 1000, isUtc: true),
);

Map<String, dynamic> requestJson(
  List<String> claims, {
  String nonce = 'n-8f3Kq2xWz0Lb',
  String clientId = 'door.harbourclub.example',
}) => {
  'client_id': clientId,
  'nonce': nonce,
  'dcql_query': {
    'credentials': [
      {
        'id': 'membership',
        'format': 'ldp_vc',
        if (claims.isNotEmpty)
          'claims': [
            for (final claim in claims)
              {
                'path': ['credentialSubject', claim],
              },
          ],
      },
    ],
  },
};

PresentationRequest request(
  List<String> claims, {
  String nonce = 'n-8f3Kq2xWz0Lb',
  String clientId = 'door.harbourclub.example',
}) => PresentationRequest.fromJson(
  requestJson(claims, nonce: nonce, clientId: clientId),
);

/// Whether [vp]'s proof verifies with the fixture holder key over the RFC 8785
/// form of [vp] without its proof.
Future<bool> holderSigned(Map<String, dynamic> vp) {
  final unsigned = Map<String, dynamic>.of(vp)..remove('proof');
  final signature = multiBaseToUint8List(vp['proof']['proofValue'] as String);
  return HolderKey.fromSeed(
    holderSeed,
  ).verify(utf8.encode(JcsUtil.canonicalize(unsigned)), signature);
}

List<String> disclosedNames(Map<String, dynamic> vp) => [
  for (final d in vp['disclosures'] as List) d['name'] as String,
];

Matcher throwsWalletException(String containing) => throwsA(
  isA<WalletException>().having((e) => e.message, 'message', contains(containing)),
);

void main() {
  test('matches the presentation the backend verifier checks', () async {
    final json = requestJson(['member']);
    final vp = await walletAt(now).createPresentation(
      credentialId,
      PresentationRequest.fromJson(json),
    );
    final vector = {'now': now, 'request': json, 'presentation': vp};
    if (Platform.environment['WALLET_VECTOR_UPDATE'] == '1') {
      vectorFile.writeAsStringSync(
        '${const JsonEncoder.withIndent('  ').convert(vector)}\n',
      );
    }
    expect(vector, jsonDecode(vectorFile.readAsStringSync()));
  });

  test('discloses exactly the claims the query names', () async {
    final vp = await walletAt(
      now,
    ).createPresentation(credentialId, request(['member', 'tier']));
    expect(disclosedNames(vp), ['member', 'tier']);
  });

  test('discloses nothing when the query names no claims', () async {
    final vp = await walletAt(
      now,
    ).createPresentation(credentialId, request([]));
    expect(vp['disclosures'], isEmpty);
  });

  test('sends the credential and each disclosure exactly as issued', () async {
    final issuance = backendIssuance();
    final vp = await walletAt(
      now,
    ).createPresentation(credentialId, request(['tier', 'birthdate']));
    expect(vp['verifiableCredential'], issuance['credential']);
    final issued = {
      for (final d in issuance['disclosures'] as List) d['name']: d,
    };
    expect(vp['disclosures'], [issued['tier'], issued['birthdate']]);
  });

  test('binds the request nonce and client_id under the holder signature', () async {
    final vp = await walletAt(now).createPresentation(
      credentialId,
      request(['member'], nonce: 'nonce-A', clientId: 'door.cedarrowing.example'),
    );
    expect(vp['nonce'], 'nonce-A');
    expect(vp['domain'], 'door.cedarrowing.example');
    expect(await holderSigned(vp), isTrue);
    expect(await holderSigned({...vp, 'nonce': 'nonce-B'}), isFalse);
    expect(
      await holderSigned({...vp, 'domain': 'door.elsewhere.example'}),
      isFalse,
    );
  });

  test('is signed by the holder key for authentication', () async {
    final vp = await walletAt(
      now,
    ).createPresentation(credentialId, request(['member']));
    final key = HolderKey.fromSeed(holderSeed);
    expect(vp['holder'], holderDid);
    expect(vp['proof'], {
      'type': 'Ed25519Signature2020',
      'created': now,
      'verificationMethod': key.keyId,
      'proofPurpose': 'authentication',
      'proofValue': startsWith('z'),
    });
    expect(await holderSigned(vp), isTrue);
  });

  test('refuses a credential that has expired', () async {
    final expiresAt = backendIssuance()['credential']['expires_at'] as int;
    await walletAt(
      expiresAt,
    ).createPresentation(credentialId, request(['member']));
    await expectLater(
      walletAt(
        expiresAt + 1,
      ).createPresentation(credentialId, request(['member'])),
      throwsWalletException('expired'),
    );
  });

  test('refuses a claim the credential does not hold', () async {
    await expectLater(
      walletAt(
        now,
      ).createPresentation(credentialId, request(['member', 'memberId'])),
      throwsWalletException('no claim memberId'),
    );
  });

  test('refuses a credential it does not hold', () async {
    await expectLater(
      walletAt(
        now,
      ).createPresentation('urn:uuid:not-held', request(['member'])),
      throwsWalletException('No credential'),
    );
  });

  test('keeps the credential and presents it again to a fresh request', () async {
    final wallet = walletAt(now);
    final first = await wallet.createPresentation(
      credentialId,
      request(['member'], nonce: 'first'),
    );
    expect(wallet.credential(credentialId), isNotNull);
    expect(wallet.heldCredentials(), hasLength(1));

    final second = await wallet.createPresentation(
      credentialId,
      request(['member'], nonce: 'second'),
    );
    expect(second['nonce'], 'second');
    expect(second['proof']['proofValue'], isNot(first['proof']['proofValue']));
    expect(await holderSigned(second), isTrue);
  });

  test('refuses a request for more than one credential', () async {
    final json = requestJson(['member']);
    final query = json['dcql_query'] as Map<String, dynamic>;
    query['credentials'] = [
      ...query['credentials'] as List,
      {'id': 'another', 'format': 'ldp_vc'},
    ];
    await expectLater(
      walletAt(
        now,
      ).createPresentation(credentialId, PresentationRequest.fromJson(json)),
      throwsWalletException('only one is supported'),
    );
  });

  test('refuses a query that offers claim sets', () async {
    final json = requestJson([]);
    final credential =
        (json['dcql_query'] as Map<String, dynamic>)['credentials'][0]
            as Map<String, dynamic>;
    credential['claims'] = [
      {
        'id': 'm',
        'path': ['credentialSubject', 'member'],
      },
      {
        'id': 't',
        'path': ['credentialSubject', 'tier'],
      },
    ];
    credential['claim_sets'] = [
      ['m'],
      ['t'],
    ];
    await expectLater(
      walletAt(
        now,
      ).createPresentation(credentialId, PresentationRequest.fromJson(json)),
      throwsWalletException('claim_sets'),
    );
  });
}

