//! The door verifies what the wallet builds.
//!
//! `app/test/fixtures/wallet_presentation.json` is the presentation the
//! wallet's `WalletService.createPresentation` produced, with the request it
//! answered; the app suite checks the wallet still produces exactly it
//! (`app/test/create_presentation_test.dart`). The credential inside is
//! `app/test/fixtures/backend_issuance.json`, issued by `Issuer::issue`.
mod common;

use std::collections::BTreeMap;

use credentials_backend::verifier::VerifyError;
use serde_json::{json, Value};

use common::*;

const VECTOR: &str = include_str!("../../app/test/fixtures/wallet_presentation.json");
const ISSUANCE: &str = include_str!("../../app/test/fixtures/backend_issuance.json");

/// The wallet fixture's holder: `HolderKey.fromSeed` of 32 bytes of 7.
const WALLET_HOLDER: &str = "did:key:z6MkvDqGT54cXesYGvABpF1UapVNwjCqRcafi4Px6Thv5T3Z";

fn vector() -> Value {
    serde_json::from_str(VECTOR).unwrap()
}

/// A door over the onboarding data whose status lists include the one the
/// wallet's credential is indexed into.
fn door(presentation: &Value) -> credentials_backend::verifier::Verifier {
    let store = store();
    let list = presentation.pointer("/verifiableCredential/credentialStatus/statusListId").and_then(Value::as_str).unwrap();
    store.allocate_status_index(list);
    verifier(store)
}

#[test]
fn the_vector_was_built_at_the_suites_now() {
    assert_eq!(vector()["now"], NOW, "the wallet signed at another time than the door checks at");
}

#[test]
fn the_door_accepts_the_presentation_the_wallet_built() {
    let vector = vector();
    let presentation = &vector["presentation"];
    let nonce = vector.pointer("/request/nonce").and_then(Value::as_str).unwrap();
    let domain = vector.pointer("/request/client_id").and_then(Value::as_str).unwrap();

    let verified = door(presentation).verify_presentation(&submission("req-1", presentation.clone()), nonce, domain).unwrap();

    assert_eq!(verified.holder, WALLET_HOLDER);
    assert_eq!(verified.credential.issuer, HARBOUR_DID);
    assert_eq!(verified.claims, BTreeMap::from([("member".to_string(), json!(true))]), "only the requested claim");
}

#[test]
fn the_wallet_signature_covers_the_nonce() {
    let vector = vector();
    let mut presentation = vector["presentation"].clone();
    presentation["nonce"] = json!("a-nonce-the-wallet-did-not-sign");
    let domain = vector.pointer("/request/client_id").and_then(Value::as_str).unwrap();

    let err = door(&presentation)
        .verify_presentation(&submission("req-1", presentation.clone()), "a-nonce-the-wallet-did-not-sign", domain)
        .unwrap_err();

    assert!(matches!(err, VerifyError::BadSignature(_)), "{err:?}");
}

#[test]
fn the_wallet_holds_a_credential_the_backend_issued() {
    let issuance: Value = serde_json::from_str(ISSUANCE).unwrap();
    let credential = &issuance["credential"];
    assert_eq!(&vector()["presentation"]["verifiableCredential"], credential, "presented unchanged");

    let verified = door(&vector()["presentation"]).verify_credential(credential).unwrap();
    assert_eq!(verified.subject, WALLET_HOLDER);
}

